def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            for k in range(max(0, i + j - N + 1), min(i + j + 1, N)):
                l = i + j - k
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])
                if k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1])
                if l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k])
                if dp[i][j][k] != -float('inf'):
                    dp[i][j][k] += grid[i][j] + (grid[k][l] if (i != k or j != l) else 0)

    return dp[N-1][N-1][N-1] if dp[N-1][N-1][N-1] != -float('inf') else 0

