def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import sys
    from collections import defaultdict

    # Parse grid values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize DP table
    dp = [[[-sys.maxsize] * N for _ in range(N)] for _ in range(N * N + 1)]
    dp[0][0][0] = grid[0][0]

    # Fill DP table
    for t in range(1, N * 2 - 1):
        for i in range(max(0, t - (N - 1)), min(N, t + 1)):
            for j in range(max(0, t - (N - 1)), min(N, t + 1)):
                x1, y1 = i, t - i
                x2, y2 = j, t - j
                if x1 >= N or y1 >= N or x2 >= N or y2 >= N:
                    continue
                current_value = grid[x1][y1] + (grid[x2][y2] if (x1, y1) != (x2, y2) else 0)
                for a in [0, 1]:
                    for b in [0, 1]:
                        ni1, nj1 = x1 + a, y1 + (1 - a)
                        ni2, nj2 = x2 + b, y2 + (1 - b)
                        if ni1 >= N or nj1 >= N or ni2 >= N or nj2 >= N:
                            continue
                        dp[t][x1][y1] = max(dp[t][x1][y1], dp[t-1][ni1][nj1] + current_value)

    return max(max(row) for row in dp[-1])

