def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_prod = 0
        for i in range(start, N - k + 1):
            current = int(num_str[start:i + 1])
            remaining = helper(i + 1, k - 1)
            max_prod = max(max_prod, current * remaining)
        return max_prod

    return helper(0, K)

