def max_product(num_str: str, N: int, K: int) -> int:
    def product_of_list(lst):
        product = 1
        for num in lst:
            product *= num
        return product

    def backtrack(start, k, current_partition):
        if k == 0:
            current_partition.append(int(num_str[start:N]))
            max_product = product_of_list(current_partition)
            current_partition.pop()
            return max_product
        max_product = 0
        for i in range(start + 1, N - k + 2):
            current_partition.append(int(num_str[start:i]))
            max_product = max(max_product, backtrack(i, k - 1, current_partition))
            current_partition.pop()
        return max_product

    return backtrack(0, K, [])

