def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        # Remove the hyphens and convert to list of characters
        chars = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += (i + 1) * int(chars[i])
        checksum = total % 11
        return checksum

    # Extract the provided checksum
    provided_checksum = isbn[-1]
    expected_checksum = calculate_checksum(isbn)

    # Determine the correct checksum character
    if expected_checksum == 10:
        correct_checksum_char = 'X'
    else:
        correct_checksum_char = str(expected_checksum)

    # Compare the provided checksum with the expected checksum
    if provided_checksum == correct_checksum_char:
        return "Right"
    else:
        # Return the corrected ISBN
        return isbn[:-1] + correct_checksum_char

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn_parts):
        total = 0
        for i, part in enumerate(isbn_parts[:-1]):
            total += int(part) * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    isbn_parts = isbn.replace('-', '')
    calculated_checksum = calculate_checksum(isbn_parts)
    expected_checksum = isbn_parts[-1]

    if calculated_checksum == expected_checksum:
        return "Right"
    else:
