def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        parts = isbn.split('-')
        digits = parts[0] + parts[1] + parts[2] + parts[3][:-1]
        total = 0
        for i, digit in enumerate(digits):
            total += (i + 1) * int(digit)
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    provided_checksum = isbn[-1]
    calculated_checksum = calculate_checksum(isbn)

    if provided_checksum == calculated_checksum:
        return "Right"
    else:
        return isbn[:-1] + calculated_checksum

