def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads array to simulate the circular nature
    beads = beads + beads[:-1]
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length
            if j > n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads array to simulate the circular nature
    beads = beads * 3
    n *= 3

    # Initialize the DP table
    dp = [[[0] * n for _ in range(n)] for _ in range(n)]

    # Fill the DP table
    for length in range(5, n + 1, 3):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i + 3, j + 1, 3):
                dp[i][j][k] = max(dp[i][j][k], dp[i][k][k] + dp[k][j][k] + beads[i] * beads[k] * beads[j])

    # Find the maximum energy in the original bead range
    max_energy = 0
    for i in range(n // 3):
        max_energy = max(max_energy, dp[i][i + n // 3 * 3 - 1][i + n // 3 * 3 - 1])

    return max_energy

def max_energy(beads):
    n = len(beads)
    beads = [0] + beads + [0]
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    for length in range(1, n + 1):
        for i in range(1, n + 2 - length):
            j = i + length
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[1][n + 1]

