def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    def is_statement_true(statement, is_liar):
        if statement in days_of_week:
            return True
        if statement.startswith("I am guilty."):
            return (scenario == statement.split()[2][:-1]) != is_liar
        if "is guilty." in statement:
            suspect = statement.split()[0]
            return (scenario == suspect) != is_liar
        return True

    for person, person_statements in statements.items():
        is_liar = person in liar_count
        for statement in person_statements:
            if not is_statement_true(statement, is_liar):
                return False
    return True

