def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # There's one way to arrange 0 pots using 0 types of flowers

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]  # Start with the number of ways without using the ith type
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # There's one way to arrange 0 pots: use no pots at all
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]  # Case 1: do not use any pots of the ith type
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD  # Case 2: use k pots of the ith type

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            start = ord('a')
        else:
            start = ord('A')
        return chr(start + (ord(c) - start - (ord(k) - start)) % 26)

    key_length = len(key)
    key = key.lower()
    decrypted_text = []

    for i, c in enumerate(ciphertext):
        if c.isalpha():
            k = key[i % key_length]
            decrypted_text.append(shift_char(c, k))
        else:
            decrypted_text.append(c)

    return ''.join(decrypted_text).lower()

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))

    key = key.lower()
    ciphertext = ciphertext.lower()
    key_length = len(key)
    key_as_int = [ord(i) - ord('a') for i in key]
    ciphertext_int = [ord(i) - ord('a') for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + ord('a'))

    return plaintext

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))

    key = key.lower()
    ciphertext = ciphertext.lower()
    decrypted_text = []
    key_length = len(key)

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        decrypted_text.append(shift_char(char, key_char))

    return ''.join(decrypted_text)

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    decrypted_text = []
    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        decrypted_text.append(chr(value + 64 + 32).lower())  # Convert to lowercase

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if aa == 0:
            return bb, 0, 1
        gcd, x1, y1 = extended_gcd(bb % aa, aa)
        x = y1 - (bb // aa) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

