def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0
    threshold = 8

    for day in range(7):
        total_hours = schedule[day][0] + schedule[day][1]
        if total_hours > threshold:
            unhappiness = total_hours - threshold
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day + 1

    return most_unhappy_day

