def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money_per_month = 300
    total_savings = 0
    for month in range(12):
        remaining_money = pocket_money_per_month - budgets[month]
        if remaining_money < 0:
            return -(month + 1)
        savings_this_month = (remaining_money // 100) * 100
        total_savings += savings_this_month
    total_savings_with_interest = total_savings * 1.2
    return int(total_savings_with_interest)

