def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate the longest increasing subsequence (LIS) ending at each position
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate the longest decreasing subsequence (LDS) starting at each position
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0

    left_increasing = [1] * n
    right_increasing = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_increasing[i] = right_increasing[i + 1] + 1

    max_formation = 0
    for i in range(n):
        max_formation = max(max_formation, left_increasing[i] + right_increasing[i] - 1)

    return n - max_formation

